import json,sys,codecs,unicodedata
assert sys.version_info[:3]==(3,14,7) and unicodedata.unidata_version=='16.0.0'
out=[]
for s in json.load(sys.stdin):
 try:
  text,n=codecs.utf_7_decode(bytes(s['input']),s['errors'],s['final']);out.append({'result':[list(map(ord,text)),n]})
 except UnicodeDecodeError as e:out.append({'error':[e.encoding,list(e.object),e.start,e.end,e.reason]})
json.dump(out,sys.stdout)
